/**
 * The bundled SRD 5.2.1 catalog (SPEC §6.1). The JSON files in data/catalog are generated by
 * the data pipeline (npm run pipeline), versioned in the repository and bundled with the app –
 * nothing is fetched from an external service at runtime. They are code-split and loaded on
 * first use of the catalog.
 */
import { catalogFileSchema, CARD_TYPES, type Card, type CardType } from '../model/schema';

type Loader = () => Promise<unknown>;

const files = import.meta.glob('../../data/catalog/*.json', { import: 'default' }) as Record<string, Loader>;

function loaderFor(type: CardType): Loader | undefined {
  return Object.entries(files).find(([path]) => path.endsWith(`/${type}.json`))?.[1];
}

export interface Catalog {
  entries: Card[];
  byType: Record<CardType, Card[]>;
}

let cached: Promise<Catalog> | null = null;

export function loadCatalog(): Promise<Catalog> {
  cached ??= (async () => {
    const byType = Object.fromEntries(CARD_TYPES.map((t) => [t, [] as Card[]])) as Record<CardType, Card[]>;
    await Promise.all(
      CARD_TYPES.map(async (type) => {
        const load = loaderFor(type);
        if (!load) return;
        const file = catalogFileSchema.parse(await load());
        byType[type] = file.entries;
      }),
    );
    return { entries: CARD_TYPES.flatMap((t) => byType[t]), byType };
  })();
  return cached;
}

/** Weapon attack entries (for "take values from weapon" in the editor). */
export async function loadWeapons(): Promise<Card[]> {
  const catalog = await loadCatalog();
  return catalog.byType.action.filter((c) => c.type === 'action' && c.action.weapon);
}
